-- ============================================================
-- pg-xerp data-layer port: frmCustomer   (posts)
-- Dialect = pg's OWN proven fast-grid (sp_brand_grid2 = 88ms/100k)
-- + xErp's sp_<formid>_<verb> naming so crud.js resolves them.
-- Table created here; procs match the form's grafted form.json.
-- ============================================================
CREATE TABLE IF NOT EXISTS public."tblfrmCustomer" (
    "Id"        bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "LedgerCode" text NOT NULL DEFAULT '',
    "LedgerGroup" text NOT NULL DEFAULT '',
    "Country" text NOT NULL DEFAULT '',
    "FCODE"     text NOT NULL DEFAULT '',
    "User_Id"   text NOT NULL DEFAULT '',
    "Lock"      smallint NOT NULL DEFAULT 0,
    "LOCK_User_Id" text NOT NULL DEFAULT '',
    "Created_At" timestamptz NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION public.sp_frmCustomer_Grid2(
    p_pagesize integer, p_pageno integer, p_search text,
    p_formid text, p_fcode text, p_auth text)
RETURNS TABLE("Id" bigint, "Detail" text, "rc" bigint)
LANGUAGE plpgsql AS $function$
BEGIN
    RETURN QUERY
    SELECT t."Id", t.det, count(*) OVER() AS rc
    FROM (
        SELECT r."Id",
               json_build_object('LedgerCode', r."LedgerCode", 'LedgerGroup', r."LedgerGroup", 'Country', r."Country")::text AS det
        FROM public."tblfrmCustomer" r
        WHERE (p_search = '' OR r."LedgerCode" ILIKE '%' || p_search || '%' OR r."LedgerGroup" ILIKE '%' || p_search || '%' OR r."Country" ILIKE '%' || p_search || '%')
        ORDER BY r."Id" DESC
        LIMIT p_pagesize OFFSET (p_pageno - 1) * p_pagesize
    ) t;
END $function$;

CREATE OR REPLACE FUNCTION public.sp_frmCustomer_GridCount1(
    p_search text, p_formid text, p_fcode text, p_auth text)
RETURNS TABLE("rc" bigint) LANGUAGE plpgsql AS $function$
BEGIN
    RETURN QUERY SELECT count(*)::bigint FROM public."tblfrmCustomer";
END $function$;

CREATE OR REPLACE FUNCTION public.sp_frmCustomer_DFE1(
    p_id bigint, p_formid text, p_auth text, p_fcode text)
RETURNS TABLE("Id" bigint, "Detail" text)
LANGUAGE plpgsql AS $function$
BEGIN
    RETURN QUERY
    SELECT r."Id", json_build_object('LedgerCode', r."LedgerCode", 'LedgerGroup', r."LedgerGroup", 'Country', r."Country")::text
    FROM public."tblfrmCustomer" r
    WHERE r."Id" = p_id;
END $function$;

CREATE OR REPLACE FUNCTION public.sp_frmCustomer_SAVE(
    p_ledgercode text, p_ledgergroup text, p_country text, p_formid text, p_fcode text, p_auth text)
RETURNS TABLE("status" text, "message" text, "id" bigint)
LANGUAGE plpgsql AS $function$
DECLARE v_id bigint;
BEGIN
    INSERT INTO public."tblfrmCustomer" ("LedgerCode", "LedgerGroup", "Country")
    VALUES (p_ledgercode, p_ledgergroup, p_country)
    RETURNING "Id" INTO v_id;
    RETURN QUERY SELECT 'Success'::text, ''::text, v_id;
END $function$;

CREATE OR REPLACE FUNCTION public.sp_frmCustomer_UPDATE(
    p_id bigint, p_ledgercode text, p_ledgergroup text, p_country text, p_formid text, p_fcode text, p_auth text)
RETURNS TABLE("status" text, "message" text)
LANGUAGE plpgsql AS $function$
BEGIN
    IF EXISTS (SELECT 1 FROM public."tblfrmCustomer" WHERE "Id" = p_id AND "Lock" = 1) THEN
        RETURN QUERY SELECT 'Error'::text, 'RECORD IS LOCKED !!!'::text;
        RETURN;
    END IF;
    UPDATE public."tblfrmCustomer" SET "LedgerCode" = p_ledgercode, "LedgerGroup" = p_ledgergroup, "Country" = p_country WHERE "Id" = p_id;
    RETURN QUERY SELECT 'Success'::text, ''::text;
END $function$;

CREATE OR REPLACE FUNCTION public.sp_frmCustomer_Delete1(
    p_id bigint, p_formid text, p_auth text)
RETURNS TABLE("status" text, "message" text)
LANGUAGE plpgsql AS $function$
BEGIN
    IF EXISTS (SELECT 1 FROM public."tblfrmCustomer" WHERE "Id" = p_id AND "Lock" = 1) THEN
        RETURN QUERY SELECT 'Error'::text, 'RECORD IS LOCKED !!!'::text;
        RETURN;
    END IF;
    DELETE FROM public."tblfrmCustomer" WHERE "Id" = p_id;
    RETURN QUERY SELECT 'Success'::text, ''::text;
END $function$;

CREATE OR REPLACE FUNCTION public.sp_frmCustomer_LockUnlock1(
    p_formid text, p_auth text, p_company text, p_id bigint)
RETURNS TABLE("status" text, "message" text) LANGUAGE plpgsql AS $function$
BEGIN
    UPDATE public."tblfrmCustomer" SET "Lock" = CASE WHEN "Lock" = 0 THEN 1 ELSE 0 END
    WHERE "Id" = p_id;
    RETURN QUERY SELECT 'Success'::text, ''::text;
END $function$;
